/**
 * AccordionSimple
 * HeroUI accordion'dan uyarlanmış — saf React implementasyonu (RAC bağımsız).
 * Compound API yerine sade API:
 *   <AccordionSimple>
 *     <AccordionSimpleItem title="Başlık" icon={<…/>} isDisabled>içerik</AccordionSimpleItem>
 *   </AccordionSimple>
 * Özellikler: allowsMultiple · isDisabled (kök + item) · kontrollü (value/onChange)
 * · özel ikon/gösterge · ayraçsız (divider={false}).
 * @id 090
 * @category Accordion
 */
import { createContext, useCallback, useContext, useId, useMemo, useState, type ReactNode } from "react"
import { cn } from "@/lib/utils"
import { ChevronDown } from "@/components/ui/icons"

/* ---------- Tip tanımları ---------- */

interface AccordionSimpleProps {
  /** Açık item key'leri (kontrollü kullanım — itemKey prop'larıyla eşleşir) */
  value?: (string | number)[]
  /** Açık item'lar değişince (kontrollü kullanım) */
  onChange?: (keys: (string | number)[]) => void
  /** İlk açık item'lar (bağımsız kullanım) */
  defaultValue?: (string | number)[]
  /** Birden fazla item aynı anda açılabilir mi (varsayılan: false) */
  allowsMultiple?: boolean
  /** Tüm accordion'ı devre dışı bırakır */
  isDisabled?: boolean
  /** Item'lar arası ayraç çizgisi (varsayılan: true) */
  divider?: boolean
  /** Görünüm: default = çizgili liste · surface = kutulu (HeroUI surface) */
  variant?: "default" | "surface"
  className?: string
  children?: ReactNode
}

interface AccordionSimpleItemProps {
  /** Açık/kapalı durumu dışarıdan takip etmek için benzersiz key (kontrollü kullanım) */
  itemKey?: string | number
  title: ReactNode
  /** Başlık solundaki ikon (opsiyonel) */
  icon?: ReactNode
  /** Varsayılan chevron yerine özel gösterge (opsiyonel) */
  indicator?: ReactNode
  /** Tek item'ı devre dışı bırakır */
  isDisabled?: boolean
  className?: string
  children?: ReactNode
}

/* ---------- Context ---------- */

interface AccordionSimpleCtx {
  expanded: Set<string>
  toggle: (key: string) => void
  allowsMultiple: boolean
  rootDisabled: boolean
  divider: boolean
}

const AccordionSimpleContext = createContext<AccordionSimpleCtx | null>(null)

/* ---------- Kök bileşen ---------- */

function AccordionSimple({
  value,
  onChange,
  defaultValue = [],
  allowsMultiple = false,
  isDisabled = false,
  divider = true,
  variant = "default",
  className,
  children,
}: AccordionSimpleProps) {
  const [internal, setInternal] = useState<(string | number)[]>(defaultValue)
  const controlled = value !== undefined
  const keys = controlled ? value : internal

  const expanded = useMemo(() => new Set(keys.map(String)), [keys])

  const toggle = useCallback(
    (key: string) => {
      if (isDisabled) return
      const next = new Set(expanded)
      if (next.has(key)) next.delete(key)
      else {
        if (!allowsMultiple) next.clear()
        next.add(key)
      }
      const arr = Array.from(next)
      if (controlled) onChange?.(arr)
      else setInternal(arr)
    },
    [expanded, allowsMultiple, isDisabled, controlled, onChange]
  )

  const ctx = useMemo<AccordionSimpleCtx>(
    () => ({ expanded, toggle, allowsMultiple, rootDisabled: isDisabled, divider }),
    [expanded, toggle, allowsMultiple, isDisabled, divider]
  )

  return (
    <AccordionSimpleContext.Provider value={ctx}>
      <div
        data-slot="accordion-simple"
        data-variant={variant}
        className={cn(
          "w-full",
          variant === "surface" && "rounded-xl border border-border/60 bg-muted/40 p-2 shadow-sm",
          className
        )}
      >
        {children}
      </div>
    </AccordionSimpleContext.Provider>
  )
}

/* ---------- Item ---------- */

function AccordionSimpleItem({
  itemKey,
  title,
  icon,
  indicator,
  isDisabled,
  className,
  children,
}: AccordionSimpleItemProps) {
  const ctx = useContext(AccordionSimpleContext)
  const fallbackKey = useId()
  const key = String(itemKey ?? fallbackKey)
  const panelId = useId()
  const open = ctx?.expanded.has(key) ?? false
  const disabled = (ctx?.rootDisabled ?? false) || isDisabled

  return (
    <div data-slot="accordion-simple-item" className={cn((ctx?.divider ?? true) && "border-b last:border-b-0", className)}>
      <h3 className="flex">
        <button
          type="button"
          aria-expanded={open}
          aria-controls={panelId}
          disabled={disabled}
          onClick={() => ctx?.toggle(key)}
          className="group/acc-simple flex flex-1 items-center justify-between gap-4 rounded-lg py-2.5 text-left text-sm font-medium outline-none transition-colors hover:underline focus-visible:ring-3 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50"
        >
          <span className="flex min-w-0 items-center gap-2">
            {icon && <span className="shrink-0 text-muted-foreground">{icon}</span>}
            <span className="truncate">{title}</span>
          </span>
          {indicator ? (
            indicator
          ) : (
            <ChevronDown
              data-slot="accordion-simple-indicator"
              className={cn("shrink-0 size-4 text-muted-foreground transition-transform duration-200", open && "rotate-180")}
            />
          )}
        </button>
      </h3>
      <div
        id={panelId}
        role="region"
        aria-labelledby={panelId}
        aria-hidden={!open}
        className={cn(
          "grid transition-[grid-template-rows] duration-200 ease-out",
          open ? "grid-rows-[1fr]" : "grid-rows-[0fr]"
        )}
      >
        <div className="overflow-hidden">
          <div className="pb-2.5 text-sm text-muted-foreground [&_a]:underline [&_a]:underline-offset-3 [&_a]:hover:text-foreground">
            {children}
          </div>
        </div>
      </div>
    </div>
  )
}

export { AccordionSimple, AccordionSimpleItem }
export type { AccordionSimpleProps, AccordionSimpleItemProps }

/**
 * BreadcrumbsSimple
 * HeroUI breadcrumbs'dan uyarlanmış — saf React implementasyonu (RAC bağımsız).
 * Otomatik chevron ayracı; son item "current" sayfa olarak işaretlenir.
 *   <BreadcrumbsSimple className="rounded-lg bg-muted/50 px-3 py-2">
 *     <BreadcrumbsSimpleItem href="#">Home</BreadcrumbsSimpleItem>
 *     <BreadcrumbsSimpleItem>Laptop</BreadcrumbsSimpleItem>
 *   </BreadcrumbsSimple>
 * @id 091
 * @category Navigasyon
 */
import { Children, cloneElement, isValidElement, type ReactNode } from "react"
import { cn } from "@/lib/utils"
import { ChevronRight } from "@/components/ui/icons"

interface BreadcrumbsSimpleProps {
  className?: string
  children?: ReactNode
}

interface BreadcrumbsSimpleItemProps {
  /** Verilirse <a> olarak render edilir; verilmezse current (son) sayfa olarak <span> */
  href?: string
  className?: string
  children?: ReactNode
}

function BreadcrumbsSimple({ className, children }: BreadcrumbsSimpleProps) {
  const items = Children.toArray(children)
  return (
    <nav aria-label="breadcrumb" className={cn("text-sm", className)}>
      <ol className="flex flex-wrap items-center gap-1.5">
        {items.map((child, i) => (
          <li key={i} className="flex items-center gap-1.5">
            {i > 0 && (
              <ChevronRight className="size-4 shrink-0 text-muted-foreground/50" aria-hidden="true" />
            )}
            {i === items.length - 1 && isValidElement(child)
              ? cloneElement(child, { "aria-current": "page" } as object)
              : child}
          </li>
        ))}
      </ol>
    </nav>
  )
}

function BreadcrumbsSimpleItem({ href, className, children }: BreadcrumbsSimpleItemProps) {
  if (href) {
    return (
      <a
        href={href}
        className={cn(
          "rounded text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-3 focus-visible:ring-ring/50",
          className
        )}
      >
        {children}
      </a>
    )
  }
  return <span className={cn("font-medium text-foreground", className)}>{children}</span>
}

export { BreadcrumbsSimple, BreadcrumbsSimpleItem }
export type { BreadcrumbsSimpleProps, BreadcrumbsSimpleItemProps }

/**
 * DateRangePickerSimple
 * Template Maker — özel bileşen (HTML'den TSX'e dönüştürüldü)
 * Basit, bağımsız tarih aralığı seçici (takvim + aralık vurgusu + temizle).
 * @id 088
 * @category Özel Komponentler
 */
import { useMemo, useState } from "react"
import { cn } from "@/lib/utils"

interface DateRangePickerSimpleProps {
  className?: string
  /** Başlangıç ve bitiş tarihi (opsiyonel, kontrollü) */
  value?: { start: Date | null; end: Date | null }
  /** Seçim değiştiğinde çağrılır */
  onChange?: (range: { start: Date | null; end: Date | null }) => void
}

const DAY_NAMES = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
const MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"]

type Cell = { day: number; month: number; year: number; other: boolean }

function buildCells(view: Date): Cell[] {
  const firstDay = new Date(view.getFullYear(), view.getMonth(), 1)
  const startOffset = (firstDay.getDay() + 6) % 7 // Pazartesi=0
  const daysInMonth = new Date(view.getFullYear(), view.getMonth() + 1, 0).getDate()
  const prevDays = new Date(view.getFullYear(), view.getMonth(), 0).getDate()
  const cells: Cell[] = []
  for (let i = startOffset; i > 0; i--) cells.push({ day: prevDays - i + 1, month: view.getMonth() - 1, year: view.getFullYear(), other: true })
  for (let d = 1; d <= daysInMonth; d++) cells.push({ day: d, month: view.getMonth(), year: view.getFullYear(), other: false })
  let next = 1
  while (cells.length % 7 !== 0) cells.push({ day: next++, month: view.getMonth() + 1, year: view.getFullYear(), other: true })
  return cells
}

function sameDay(a: Date, b: Date) {
  return b && a.toDateString() === b.toDateString()
}

function DateRangePickerSimple({ className, value, onChange }: DateRangePickerSimpleProps) {
  const [view, setView] = useState(() => new Date(2026, 8, 1))
  const [internal, setInternal] = useState<{ start: Date | null; end: Date | null }>({
    start: new Date(2026, 8, 1),
    end: new Date(2026, 8, 9),
  })

  const range = value ?? internal
  const setRange = (r: { start: Date | null; end: Date | null }) => {
    setInternal(r)
    onChange?.(r)
  }

  const cells = useMemo(() => buildCells(view), [view])

  const selectDate = (y: number, m: number, d: number) => {
    const picked = new Date(y, m, d)
    if (!range.start || (range.start && range.end)) {
      setRange({ start: picked, end: null })
    } else if (!range.end) {
      if (picked < range.start) setRange({ end: range.start, start: picked })
      else setRange({ start: range.start, end: picked })
    }
  }

  const changeMonth = (delta: number) => {
    setView(new Date(view.getFullYear(), view.getMonth() + delta, 1))
  }

  const clear = () => setRange({ start: null, end: null })

  return (
    <div className={cn("w-[340px] rounded-[10px] bg-white p-[18px_20px] shadow-[0_2px_12px_rgba(0,0,0,.08)]", className)}>
      {/* Üst bar: ay/yıl gezinme + temizle */}
      <div className="mb-3.5 flex items-center justify-center gap-3.5">
        <button
          onClick={() => changeMonth(-1)}
          aria-label="Önceki ay"
          className="flex h-7 w-7 cursor-pointer items-center justify-center rounded-md border-none bg-slate-100 text-sm text-[#555] transition-colors hover:bg-slate-200"
        >‹</button>
        <span className="flex cursor-pointer items-center gap-1 text-[15px] font-semibold text-[#222]">
          {MONTH_NAMES[view.getMonth()]}
          <span className="text-xs text-[#888]">⌄</span>
        </span>
        <span className="flex cursor-pointer items-center gap-1 text-[15px] font-semibold text-[#222]">
          {view.getFullYear()}
          <span className="text-xs text-[#888]">⌄</span>
        </span>
        <button
          onClick={() => changeMonth(1)}
          aria-label="Sonraki ay"
          className="flex h-7 w-7 cursor-pointer items-center justify-center rounded-md border-none bg-slate-100 text-sm text-[#555] transition-colors hover:bg-slate-200"
        >›</button>
        <button
          onClick={clear}
          title="Temizle"
          aria-label="Seçimi temizle"
          className="ml-auto flex h-7 w-7 cursor-pointer items-center justify-center rounded-md border-none bg-slate-100 text-sm text-[#555] transition-colors hover:bg-red-100 hover:text-red-600"
        >✕</button>
      </div>

      {/* Gün adları */}
      <div className="mb-1 grid grid-cols-7 text-center">
        {DAY_NAMES.map((d) => (
          <div key={d} className="py-1.5 text-xs font-semibold text-[#8b93a1]">{d}</div>
        ))}
      </div>

      {/* Takvim hücreleri */}
      <div className="grid grid-cols-7 gap-y-1.5">
        {cells.map((c, idx) => {
          const date = new Date(c.year, c.month, c.day)
          const inRange = range.start && range.end && date >= range.start && date <= range.end
          const isOnlyStart = range.start && !range.end && sameDay(date, range.start)
          const col = idx % 7

          let cls = "relative flex h-[34px] cursor-pointer items-center justify-center text-sm text-[#3a3f4b]"
          if (c.other) cls += " text-[#c7cbd3]"
          if (inRange) {
            cls += " bg-[#0b84fe] text-white"
            if (c.other) cls += " text-white/60"
            if (sameDay(date, range.start as Date) || col === 0) cls += " rounded-l-[17px]"
            if (sameDay(date, range.end as Date) || col === 6) cls += " rounded-r-[17px]"
          } else if (isOnlyStart) {
            cls += " rounded-l-[17px] rounded-r-[17px] bg-[#0b84fe] text-white"
          }

          return (
            <div key={idx} className={cls} onClick={() => selectDate(c.year, c.month, c.day)}>
              {c.day}
            </div>
          )
        })}
      </div>
    </div>
  )
}

export { DateRangePickerSimple }
export type { DateRangePickerSimpleProps }

/**
 * MillerColumns
 * Template Maker — özel bileşen (React + Tailwind Miller Columns navigatörü)
 * Hiyerarşik veriyi sütunlar halinde gezinme (dosya yöneticisi tarzı).
 * @id 089
 * @category Özel Komponentler
 */
import { Fragment, useCallback, useEffect, useMemo, useRef, useState } from "react"

/* ---------- Tipler ---------- */
export interface TreeNode {
  id: string
  label?: string
  title?: string
  children?: TreeNode[]
}

export interface MillerColumnsProps {
  /** Ağaç verisi (id + çocuklar; label/title görüntülenir) */
  data: TreeNode[]
  /** Başlangıç yolu, örn. ["eng","fe","react"] */
  initialPath?: string[]
  /** Her gezinmede çağrılır: (path, son node) */
  onChange?: (path: string[], node: TreeNode | null) => void
  /** Kök için ekstra sınıflar */
  className?: string
}

/* ---------- Yardımcılar ---------- */
function getLabel(node: TreeNode | null | undefined): string {
  return node?.label ?? node?.title ?? node?.id ?? ""
}

function findById(nodes: TreeNode[], id: string): TreeNode | null {
  for (const n of nodes) {
    if (n.id === id) return n
    const found = findById(n.children || [], id)
    if (found) return found
  }
  return null
}

function getNodesByPath(roots: TreeNode[], path: string[]): (TreeNode | null)[] {
  const out: (TreeNode | null)[] = []
  let cur = roots
  for (const id of path) {
    const node = cur.find((n) => n.id === id) || null
    out.push(node)
    if (node) cur = node.children || []
    else break
  }
  return out
}

/* ---------- Alt bileşenler ---------- */
function ChevronRight() {
  return (
    <svg
      width="13" height="13" viewBox="0 0 24 24" fill="none"
      stroke="currentColor" strokeWidth="2" strokeLinecap="round"
      strokeLinejoin="round" aria-hidden="true"
    >
      <polyline points="9 18 15 12 9 6" />
    </svg>
  )
}

function Breadcrumb({
  path, nodes, onCrumbClick,
}: { path: string[]; nodes: (TreeNode | null)[]; onCrumbClick: (i: number) => void }) {
  if (path.length === 0) {
    return (
      <div className="flex h-8 items-center gap-1 border-b border-slate-200 bg-slate-50 px-4" aria-label="Breadcrumb">
        <span className="font-mono text-[11px] uppercase tracking-widest text-slate-400">
          / root
        </span>
      </div>
    )
  }
  return (
    <nav
      aria-label="Breadcrumb"
      className="flex h-8 items-center gap-1 overflow-x-auto border-b border-slate-200 bg-slate-50 px-4"
    >
      <button
        type="button"
        onClick={() => onCrumbClick(-1)}
        className="flex-shrink-0 font-mono text-[11px] uppercase tracking-wider text-slate-500 transition-colors hover:text-slate-300"
      >
        root
      </button>
      {nodes.map((node, i) =>
        node ? (
          <Fragment key={node.id}>
            <span className="flex-shrink-0 text-[11px] text-slate-400">/</span>
            <button
              type="button"
              onClick={() => onCrumbClick(i)}
              aria-current={i === nodes.length - 1 ? "page" : undefined}
              className={`flex-shrink-0 font-mono text-[11px] uppercase tracking-wider transition-colors ${
                i === nodes.length - 1 ? "text-blue-600" : "text-slate-500 hover:text-slate-800"
              }`}
            >
              {getLabel(node)}
            </button>
          </Fragment>
        ) : null
      )}
    </nav>
  )
}

function ColumnItem({
  node, depth, isSelected, onClick,
}: { node: TreeNode; depth: number; isSelected: boolean; onClick: () => void }) {
  const hasChildren = (node.children || []).length > 0
  return (
    <button
      type="button"
      role="treeitem"
      aria-level={depth + 1}
      aria-selected={isSelected}
      aria-expanded={hasChildren ? true : undefined}
      onClick={onClick}
      className={`group relative flex w-full items-center justify-between px-3 py-2 text-left font-mono transition-colors ${
        isSelected ? "bg-blue-600 text-white" : "text-slate-500 hover:bg-slate-100 hover:text-slate-900"
      }`}
    >
      {isSelected && <span className="absolute left-0 top-0 h-full w-0.5 bg-blue-500" />}
      <span className="truncate pr-2 text-[13px]">{getLabel(node)}</span>
      {hasChildren && (
        <span className={`flex-shrink-0 transition-colors ${isSelected ? "text-white" : "text-slate-400 group-hover:text-slate-400"}`}>
          <ChevronRight />
        </span>
      )}
    </button>
  )
}

function ColumnPanel({
  nodes, selectedId, headerLabel, depth, isLeaf, onSelect,
}: {
  nodes: TreeNode[]; selectedId: string | null; headerLabel: string
  depth: number; isLeaf: boolean; onSelect: (node: TreeNode) => void
}) {
  return (
    <section
      aria-label={headerLabel}
      className="miller-col-enter flex w-72 flex-shrink-0 flex-col border-r border-slate-200"
      style={{ backgroundColor: "#f8fafc" }}
    >
      <div className="flex-shrink-0 border-b border-slate-200 bg-slate-50 px-3 py-2">
        <div className="text-[10px] font-semibold uppercase tracking-widest text-slate-500">
          {headerLabel}
        </div>
        <div className="mt-0.5 font-mono text-[10px] text-slate-400">depth/{depth}</div>
      </div>
      {isLeaf ? (
        <div className="flex flex-1 items-center justify-center p-4">
          <div className="text-center">
            <div className="mb-1 text-[11px] uppercase tracking-wider text-slate-500">Terminal node</div>
            <div className="font-mono text-[12px] text-slate-400">no children</div>
          </div>
        </div>
      ) : nodes.length === 0 ? (
        <div className="flex flex-1 items-center justify-center font-mono text-[12px] text-slate-400">empty</div>
      ) : (
        <div className="miller-vscroll flex-1 overflow-y-auto py-1" role="group">
          {nodes.map((node) => (
            <ColumnItem
              key={node.id}
              node={node}
              depth={depth}
              isSelected={node.id === selectedId}
              onClick={() => onSelect(node)}
            />
          ))}
        </div>
      )}
    </section>
  )
}

/* ---------- Ana bileşen ---------- */
export function MillerColumns({
  data, initialPath = [], onChange, className = "",
}: MillerColumnsProps) {
  const [path, setPath] = useState<string[]>(() => initialPath)

  const onChangeRef = useRef(onChange)
  useEffect(() => {
    onChangeRef.current = onChange
  }, [onChange])

  useEffect(() => {
    if (!onChangeRef.current) return
    const last = path.length > 0 ? findById(data, path[path.length - 1]) : null
    onChangeRef.current(path, last)
  }, [path, data])

  const pathNodes = useMemo(() => getNodesByPath(data, path), [data, path])

  const columns = useMemo(() => {
    const cols: { nodes: TreeNode[]; headerLabel: string; depth: number; selectedId: string | null; isLeaf: boolean }[] = [
      { nodes: data, headerLabel: "All", depth: 0, selectedId: path[0] ?? null, isLeaf: false },
    ]
    let cur = data
    for (let i = 0; i < path.length; i++) {
      const node = cur.find((n) => n.id === path[i])
      if (!node) break
      const kids = node.children || []
      if (kids.length === 0) {
        cols.push({ nodes: [], headerLabel: getLabel(node), depth: i + 1, selectedId: null, isLeaf: true })
        break
      }
      cols.push({ nodes: kids, headerLabel: getLabel(node), depth: i + 1, selectedId: path[i + 1] ?? null, isLeaf: false })
      cur = kids
    }
    return cols
  }, [data, path])

  const columnKey = (col: { depth: number }) =>
    col.depth === 0 ? "__root__" : path.slice(0, col.depth).join("/")

  const scrollRef = useRef<HTMLDivElement | null>(null)
  useEffect(() => {
    const c = scrollRef.current
    if (!c) return
    const raf = requestAnimationFrame(() => {
      c.scrollTo({ left: c.scrollWidth, behavior: "smooth" })
    })
    return () => cancelAnimationFrame(raf)
  }, [path])

  const handleSelect = useCallback((depth: number, node: TreeNode) => {
    setPath((prev) => [...prev.slice(0, depth), node.id])
  }, [])

  const handleCrumb = useCallback((idx: number) => {
    setPath((prev) => (idx < 0 ? [] : prev.slice(0, idx + 1)))
  }, [])

  return (
    <div className={`flex h-full w-full flex-col bg-white text-slate-800 ${className}`}>
      <Breadcrumb path={path} nodes={pathNodes} onCrumbClick={handleCrumb} />
      <div
        ref={scrollRef}
        className="miller-hscroll flex flex-1 flex-row overflow-x-auto overflow-y-hidden"
        role="tree"
        aria-label="Miller columns navigator"
      >
        {columns.map((col) => (
          <ColumnPanel
            key={columnKey(col)}
            nodes={col.nodes}
            selectedId={col.selectedId}
            headerLabel={col.headerLabel}
            depth={col.depth}
            isLeaf={col.isLeaf}
            onSelect={(node) => handleSelect(col.depth, node)}
          />
        ))}
        <div className="w-px flex-shrink-0" />
      </div>

      <style>{`
        .miller-hscroll { scrollbar-width: thin; scrollbar-color: #cbd5e1 transparent; }
        .miller-hscroll::-webkit-scrollbar { height: 4px; }
        .miller-hscroll::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 2px; }
